source("/private/tmp/claude-501/-Users-pbtz-src-github-com-pedrobtz-zuspark/23786a96-505c-4b1e-b66f-e320fa1ada7b/scratchpad/hunt/hunt-2/harness.R")
all4 <- list(B(1), B(2), B(3), B(4)); P <- function(n) rep(list(PROG()), n)
INT <- structure(class = c("zugrpc_error_interrupt", "zugrpc_error", "error", "condition"), list(message = "The call was interrupted.", call = NULL, grpc_status = "CANCELLED"))
cat("## Ctrl-C lands in the inline release (17th response pending)\n")
k <- 0
srv <- new_server(list(c(all4, P(14), list(RC()))), list(ReleaseExecute = function(req, srv) { k <<- k + 1; if (k == 1) stop(INT); list(operation_id = req$operation_id) }))
con <- srv$connect(); q <- new_q(con); e <- try_show(spark_collect(q)); srv$show(); cat("   op on error:", e$operation_id, "\n")
cat("## Ctrl-C lands in the final release, result complete\n")
srv <- new_server(list(c(all4, list(RC()))), list(ReleaseExecute = function(req, srv) stop(INT)))
con <- srv$connect(); q <- new_q(con); e <- try_show(spark_collect(q)); srv$show()
cat("## deadlines per call\n")
srv <- new_server(list(list(B(1), transport_cnd()), c(all4[-1], P(14), list(RC()))))
con <- srv$connect(deadline = 12); q <- new_q(con); d <- spark_collect(q); spark_interrupt(con); spark_config(con, "a"); spark_disconnect(con)
for (l in srv$log) cat("   ", l$method, "deadline:", if (is.null(l$deadline)) "NULL" else format(l$deadline), "\n")
cat("## every request carries session fields\n")
ok <- TRUE; for (l in srv$log) { r <- l$req; good <- identical(r$session_id, con$session_id) && identical(r$user_context$user_id, "hunter") && grepl("^zuspark zuspark/", r$client_type) && (l$method == "ReleaseSession" || identical(r$client_observed_server_side_session_id, SERVER_SID)); if (!good) cat("   BAD:", l$method, "\n"); ok <- ok && good }
cat("   all good:", ok, "\n")
cat("## a released connection: collect of an old query, interrupt, error details, schema\n")
srv <- new_server(list(c(all4, list(RC())))); con <- srv$connect(); q <- new_q(con); spark_disconnect(con); srv$log <- list()
try_show(spark_collect(q)); try_show(spark_fetch(q)); try_show(spark_interrupt(con)); try_show(zuspark::spark_schema(q)); try_show(spark_error_details(zuspark:::as_zuspark_error(spark_cnd(), con)))
cat("   calls after release:", length(srv$log), "\n")
cat("## disconnect while a query is half-read in on_response (released mid-stream)\n")
srv <- new_server(list(c(all4, list(RC())))); con <- srv$connect()
r <- try_show(zuspark:::execute_plan(con, list(root = sql_relation), on_response = function(resp) spark_disconnect(con))); srv$show()
